package com.engine.nested;

import java.util.ArrayList;
import java.util.List;

public class TaskExecutionEngine {
    private final String engineId;
    private final List<String> tasks = new ArrayList<>();

    public TaskExecutionEngine(String engineId) {
        this.engineId = engineId;
    }

    // 1. Static Nested Class: Independent of outer instance
    public static class EngineConfig {
        private int maxThreads = 4;

        public void setMaxThreads(int maxThreads) {
            this.maxThreads = maxThreads;
        }
    }

    // 2. Inner Class (Non-Static): Bound to outer instance
    public class TaskIterator {
        private int currentIndex = 0;

        public boolean hasNext() {
            // Directly accesses outer class private field 'tasks'
            return currentIndex < tasks.size();
        }

        public String next() {
            // Accesses outer instance field and demonstrates explicit outer 'this' syntax
            System.out.println("Iterating in engine: " + TaskExecutionEngine.this.engineId);
            return tasks.get(currentIndex++);
        }
    }

    public void executeBatch(List<String> rawTasks) {
        // Effectively final local variable captured by local and anonymous classes
        final String batchPrefix = "BATCH-";

        // 3. Local Class: Defined inside a method block
        class TaskValidator {
            boolean isValid(String task) {
                // Accesses outer instance field and captured local variable
                return task != null && task.startsWith(batchPrefix) && !engineId.isEmpty();
            }
        }

        TaskValidator validator = new TaskValidator();

        for (String rawTask : rawTasks) {
            if (validator.isValid(rawTask)) {
                tasks.add(rawTask);
            }
        }

        // 4. Anonymous Class: Expression-based instantiation of an interface
        Runnable processor = new Runnable() {
            @Override
            public void run() {
                // Accesses outer instance and captured local variables
                System.out.println("Processing " + tasks.size() + " tasks for prefix: " + batchPrefix);
            }
        };

        new Thread(processor).start();
    }
}
